import figure5 from "../assets/inertial-fixed-mechanics-force-limit-20261005.svg";
const sections=[{"id": "report:nested:intro", "title": "Intro", "depth": 2, "path": ["Intro"], "children": [], "queryIds": ["fixed_mechanics_contract", "single_axis_prototype_scope"], "fragments": [{"kind": "prose", "id": "report:nested:intro:part-0", "value": "## Intro"}, {"kind": "prose", "id": "report:nested:intro:part-1", "value": "Our goal is a flange that keeps the **normal pressing force experienced by the workpiece within ±0.5 N**, including a **1 mm high, 10 mm wide bump crossed at 100 mm/s**. The required operating range is **5–50 N**, tool masses of **0.1–2 kg**, and fixed flange orientations from **0–90°**.\n\nFor the **first prototype**, we will use a **one-axis load cell plus tool acceleration** and ignore drag coupling into that axis. Separating normal force from sanding drag on slopes remains an open problem requiring multi-axis force sensing. We defer that extension for now.\n\nThe mechanics are prescribed: a **20 N/mm upper spring with zero external damping and unlimited ideal length/travel**, and a **rigid lower attachment**. The load cell still has finite stiffness. The actuator has a real stroke limit. We may use measured force, tool acceleration, tool position relative to the flange body, and robot commands already issued. The controller receives no surface preview.\n\n**A** is the actuator body, **B** the 0.6 kg moving holder, and **S** the tool beyond the load cell. Full-range reference tests use A = 1.5 kg for realistic body/mounting mass. Taring tool weight removes gravity, but not dynamic inertia."}]}, {"id": "report:nested:question", "title": "Question", "depth": 2, "path": ["Question"], "children": [], "queryIds": ["fixed_mechanics_contract", "single_axis_prototype_scope"], "fragments": [{"kind": "prose", "id": "report:nested:question:part-0", "value": "## Question"}, {"kind": "prose", "id": "report:nested:question:part-1", "value": "Can this arrangement meet the force requirement, and what actuator, load cell, accelerometer and acquisition electronics should we use for a first prototype? In particular, where can we reduce cost without accepting too much force error?"}]}, {"id": "report:nested:results", "title": "Results", "depth": 2, "path": ["Results"], "children": [{"id": "report:nested:results:mechanics-load-path-springs-and-guides", "title": "Mechanics: load path, springs and guides", "depth": 3, "path": ["Results", "Mechanics: load path, springs and guides"], "children": [{"id": "report:nested:results:mechanics-load-path-springs-and-guides:intro", "title": "Intro", "depth": 4, "path": ["Results", "Mechanics: load path, springs and guides", "Intro"], "children": [], "queryIds": ["fixed_mechanics_contract", "fixed_development_results", "fixed_qualification_results", "fixed_control_waveform", "explained_cell_mode"], "fragments": [{"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:intro:part-0", "value": "#### Intro"}, {"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:intro:part-1", "value": "The upper spring connects the robot to A. The actuator moves B relative to A. The load cell connects B to S, and the surface supports S while contact is maintained."}, {"kind": "figure", "id": "inertial:prototype-mechanics-single-axis-20261006", "title": "Prescribed mechanics and first-prototype measurement locations", "caption": "Position measures S relative to A. The load cell carries the entire tool S; an accelerometer is mounted on S.", "queryId": "single_axis_prototype_scope", "asset": "figure1"}]}, {"id": "report:nested:results:mechanics-load-path-springs-and-guides:question", "title": "Question", "depth": 4, "path": ["Results", "Mechanics: load path, springs and guides", "Question"], "children": [], "queryIds": ["fixed_mechanics_contract", "fixed_development_results", "fixed_qualification_results", "fixed_control_waveform", "explained_cell_mode"], "fragments": [{"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:question:part-0", "value": "#### Question"}, {"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:question:part-1", "value": "What is a mechanical “mode,” and why can a nominally rigid connection still cause force ringing?"}]}, {"id": "report:nested:results:mechanics-load-path-springs-and-guides:results", "title": "Results", "depth": 4, "path": ["Results", "Mechanics: load path, springs and guides", "Results"], "children": [], "queryIds": ["fixed_mechanics_contract", "fixed_development_results", "fixed_qualification_results", "fixed_control_waveform", "explained_cell_mode"], "fragments": [{"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:results:part-0", "value": "#### Results"}, {"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:results:part-1", "value": "A **mode** is a characteristic pattern of vibration: which parts move relative to one another, and how quickly they oscillate. A disturbed mass on a spring rings in one such pattern; a structure can have several. [Modal-analysis explanation](https://www.mathworks.com/discovery/modal-analysis.html).\n\nThe upper spring permits relatively slow body motion. A different, much faster mode involves tiny deformation of the load cell and movement of B relative to S. With the reference **64 MN/m cell stiffness** and 0.6 kg holder, its frequency is about **1.64 kHz**, or one cycle every **0.61 ms**. A 0.5 N cell-force change requires only **7.8 nanometres** of deformation. “Rigidly mounted” therefore does not mean mechanically infinitely stiff.\n\nThe native Simulink plant applies mass force balances, gravity, surface geometry, drag, coil electrical dynamics and guide friction. Zero external damping leaves the assumed internal **0.2 N Coulomb friction and 2 N·s/m viscous friction**. Maintained contact makes S follow the smooth bump; the simulation stops when contact or travel limits fail."}, {"kind": "figure", "id": "inertial:load-cell-mode-explained-20261006", "title": "Load-cell mode and the purpose of its feedback", "caption": "The mechanical motion is schematic and exaggerated. The feedback uses acquired axial load-cell data; it has no access to future surface shape.", "queryId": "explained_cell_mode", "asset": "figure2"}]}, {"id": "report:nested:results:mechanics-load-path-springs-and-guides:recommendation", "title": "Recommendation", "depth": 4, "path": ["Results", "Mechanics: load path, springs and guides", "Recommendation"], "children": [], "queryIds": ["fixed_mechanics_contract", "fixed_development_results", "fixed_qualification_results", "fixed_control_waveform", "explained_cell_mode"], "fragments": [{"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:recommendation:part-0", "value": "#### Recommendation"}, {"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:recommendation:part-1", "value": "Keep the prescribed spring and lower attachment. Measure the assembled cell/frame/guide vibration frequencies and friction before tuning the controller. Real sensor or mounting stiffness can shift the ringing frequency substantially; the present narrow-band correction must then be identified again."}]}], "queryIds": ["fixed_mechanics_contract", "fixed_development_results", "fixed_qualification_results", "fixed_control_waveform", "explained_cell_mode"], "fragments": [{"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:part-0", "value": "### Mechanics: load path, springs and guides"}]}, {"id": "report:nested:results:actuator-and-electrical-drive", "title": "Actuator and electrical drive", "depth": 3, "path": ["Results", "Actuator and electrical drive"], "children": [{"id": "report:nested:results:actuator-and-electrical-drive:intro", "title": "Intro", "depth": 4, "path": ["Results", "Actuator and electrical drive", "Intro"], "children": [], "queryIds": ["fixed_mechanics_contract", "fixed_development_results", "fixed_qualification_results", "fixed_control_waveform", "fixed_voltage_diagnostics", "coil_parts", "final_actuator_comparison", "actuator_sizing_reviewed"], "fragments": [{"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:intro:part-0", "value": "#### Intro"}, {"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:intro:part-1", "value": "The actuator must change force quickly while supporting sustained sanding loads, within the moving-mass and thermal budgets."}]}, {"id": "report:nested:results:actuator-and-electrical-drive:question", "title": "Question", "depth": 4, "path": ["Results", "Actuator and electrical drive", "Question"], "children": [], "queryIds": ["fixed_mechanics_contract", "fixed_development_results", "fixed_qualification_results", "fixed_control_waveform", "fixed_voltage_diagnostics", "coil_parts", "final_actuator_comparison", "actuator_sizing_reviewed"], "fragments": [{"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:question:part-0", "value": "#### Question"}, {"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:question:part-1", "value": "Why start with a voice coil rather than a leadscrew, and which voice-coil parameters should we look for?"}]}, {"id": "report:nested:results:actuator-and-electrical-drive:results", "title": "Results", "depth": 4, "path": ["Results", "Actuator and electrical drive", "Results"], "children": [], "queryIds": ["fixed_mechanics_contract", "fixed_development_results", "fixed_qualification_results", "fixed_control_waveform", "fixed_voltage_diagnostics", "coil_parts", "final_actuator_comparison", "actuator_sizing_reviewed"], "fragments": [{"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:results:part-0", "value": "#### Results"}, {"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:results:part-1", "value": "A voice coil makes linear force directly: **force ≈ force constant × current**. A leadscrew converts rotation into linear motion, providing mechanical advantage but adding rotational inertia, friction and possible backlash to the force-control problem.\n\nThe modeled bump requires **34.35 mm/s peak tool speed and 2.4 m/s² peak acceleration**. At S = 2 kg, tool inertia alone changes the support-force measurement by **4.8 N**. These are tool motion values; actuator travel also depends on A moving on the upper spring.\n\nThe RE25 sizing comparison shows the trade-off. At **10 mm screw lead**, holding 50 N ideally needs about **3.40 A**, above that motor's **1.16 A continuous rating**. A 3 mm lead reduces this to 1.02 A before losses, but increases the equivalent translating rotary inertia from **0.624 kg to 6.93 kg**. This is the extra mass the motor's rotational inertia effectively adds when accelerating the tool."}, {"kind": "figure", "id": "inertial:leadscrew-pitch-inertia-current-20261006", "title": "Leadscrew pitch trades holding current against effective inertia", "caption": "Analytical RE25 sizing, separate from the native transmission model. Friction and efficiency add to the ideal holding demand.", "queryId": "actuator_sizing_reviewed", "asset": "figure3"}, {"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:results:part-2", "value": "Both actuators passed four historical transient tests with different mechanics. A larger motor or transmission could work; these results favour a voice coil without ruling out all leadscrews.\n\nFor a coil, examine the following parameters together:"}, {"kind": "table", "id": "report:nested:results:actuator-and-electrical-drive:results:table-1", "title": "Results · Actuator and electrical drive", "queryIds": ["fixed_mechanics_contract", "fixed_development_results", "fixed_qualification_results", "fixed_control_waveform", "fixed_voltage_diagnostics", "coil_parts", "final_actuator_comparison", "actuator_sizing_reviewed"], "headers": ["Parameter", "Development target and reason"], "rows": [{"column0": "Force constant", "column1": "Around **24.4–25 N/A**, specified over the used stroke; converts force demand into current"}, {"column0": "Continuous force", "column1": "At least **55–60 N at the actual hot temperature and stroke**, with the specified mounting/cooling"}, {"column0": "Peak force/current", "column1": "About **85 N / 3.5 A**, with permitted pulse duration and duty cycle"}, {"column0": "Travel", "column1": "**25 mm**, retaining a ±7.5 mm working band about the midpoint"}, {"column0": "Resistance and inductance", "column1": "Reference: **6.4 Ω cold, 8.896 Ω modeled hot, 4 mH**; these set heat and current-slew voltage"}, {"column0": "Mass", "column1": "Include moving coil in B and stationary body/mount in A; the reference body alone is about **1.24 kg**"}], "rightAligned": [false, false]}, {"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:results:part-3", "value": "Voltage demand is **V = RI + L·dI/dt + Kf·v**: winding resistance, changing current and motion-induced voltage all matter. A steady 50 N hot-coil hold needs **2.05 A and 37.4 W**. Check sustained hot force near stroke ends, not just catalog cold/centre ratings.\n\nHigher voltage helps only when the driver is clipping. One unchanged-controller nominal run is bitwise identical at 32 and 48 V. In a clipped stress case, raising usable voltage reduces error from **2.748 to 0.650 N** and removes clipping; demand reaches **33.02 V**. Both stressed runs fail ±0.5 N. Extra voltage addresses one limitation, while sensing, ringing and robot motion remain relevant."}]}, {"id": "report:nested:results:actuator-and-electrical-drive:recommendation", "title": "Recommendation", "depth": 4, "path": ["Results", "Actuator and electrical drive", "Recommendation"], "children": [], "queryIds": ["fixed_mechanics_contract", "fixed_development_results", "fixed_qualification_results", "fixed_control_waveform", "fixed_voltage_diagnostics", "coil_parts", "final_actuator_comparison", "actuator_sizing_reviewed"], "fragments": [{"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:recommendation:part-0", "value": "#### Recommendation"}, {"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:recommendation:part-1", "value": "Use a voice coil for the first prototype, with an adjustable **48 V-rated bipolar driver** and a **≥36 V usable-output development target**. Check actual winding voltage after driver losses. Provide a separate fast current-measurement loop, overtemperature protection and adequate cooling. The evaluated controller used 32 V; this recommendation is not a newly qualified 36/48 V configuration."}]}], "queryIds": ["fixed_mechanics_contract", "fixed_development_results", "fixed_qualification_results", "fixed_control_waveform", "fixed_voltage_diagnostics", "coil_parts", "final_actuator_comparison", "actuator_sizing_reviewed"], "fragments": [{"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:part-0", "value": "### Actuator and electrical drive"}]}, {"id": "report:nested:results:force-and-position-measurement", "title": "Force and position measurement", "depth": 3, "path": ["Results", "Force and position measurement"], "children": [{"id": "report:nested:results:force-and-position-measurement:intro", "title": "Intro", "depth": 4, "path": ["Results", "Force and position measurement", "Intro"], "children": [], "queryIds": ["fixed_mechanics_contract", "force_position_parts", "joint_budget_plan", "single_axis_prototype_scope", "loadcell_scope_evidence"], "fragments": [{"kind": "prose", "id": "report:nested:results:force-and-position-measurement:intro:part-0", "value": "#### Intro"}, {"kind": "prose", "id": "report:nested:results:force-and-position-measurement:intro:part-1", "value": "The B–S load cell measures the force supporting the tool. That includes the surface reaction, tool inertia and, before tare, gravity. It is not automatically the force pressing normally into the workpiece."}]}, {"id": "report:nested:results:force-and-position-measurement:question", "title": "Question", "depth": 4, "path": ["Results", "Force and position measurement", "Question"], "children": [], "queryIds": ["fixed_mechanics_contract", "force_position_parts", "joint_budget_plan", "single_axis_prototype_scope", "loadcell_scope_evidence"], "fragments": [{"kind": "prose", "id": "report:nested:results:force-and-position-measurement:question:part-0", "value": "#### Question"}, {"kind": "prose", "id": "report:nested:results:force-and-position-measurement:question:part-1", "value": "What kind of load cell do we need, and can we get away with a single force axis?"}]}, {"id": "report:nested:results:force-and-position-measurement:results", "title": "Results", "depth": 4, "path": ["Results", "Force and position measurement", "Results"], "children": [], "queryIds": ["fixed_mechanics_contract", "force_position_parts", "joint_budget_plan", "single_axis_prototype_scope", "loadcell_scope_evidence"], "fragments": [{"kind": "prose", "id": "report:nested:results:force-and-position-measurement:results:part-0", "value": "#### Results"}, {"kind": "prose", "id": "report:nested:results:force-and-position-measurement:results:part-1", "value": "**Yes, for our reduced first-prototype scope.** With known tool mass and consistent gravity tare, add **S mass × measured S acceleration** to the axial cell reading. This reconstructs axial contact force: tool acceleration contributes 4.8 N at the heavy-tool bump peak, so static zeroing alone is insufficient. Holder B is upstream of the cell and is not part of this inertia correction.\n\nOn an aligned flat test surface, axial contact force is normal pressing force. On a slope, the estimate also needs surface direction: without drag, divide the axial component by the cosine of the angle between the sensor axis and surface normal. S–A position and measured motion help estimate that direction causally.\n\n**Open problem: sanding drag.** Drag is tangent to the surface, but on a slope it can project onto a fixed sensor axis. Acceleration removes inertia; it cannot separate two unknown contact-force components. Addressing this needs two force axes for planar sanding, or three for spatial sanding. We will ignore this coupling for now; [the geometry and measurement evidence](/home/tommie/Projects/actuator-model/acf_simulink/experiments/report_readability_20261006/loadcell/README.md) remain available for the later extension.\n\nRaw axial cell force ranges from **−18.9 to +59.8 N** in the 736 reference tests. A roughly **±100 N measurement range** is a reasonable sizing target with reserve. The earlier ±160 N number is **ADC electrical scaling**, not a required physical cell rating."}]}, {"id": "report:nested:results:force-and-position-measurement:recommendation", "title": "Recommendation", "depth": 4, "path": ["Results", "Force and position measurement", "Recommendation"], "children": [], "queryIds": ["fixed_mechanics_contract", "force_position_parts", "joint_budget_plan", "single_axis_prototype_scope", "loadcell_scope_evidence"], "fragments": [{"kind": "prose", "id": "report:nested:results:force-and-position-measurement:recommendation:part-0", "value": "#### Recommendation"}, {"kind": "prose", "id": "report:nested:results:force-and-position-measurement:recommendation:part-1", "value": "Use a **one-axis cell between B and S**, with an accelerometer on S and position measured from S to A. Target **±0.01 N residual zero**, **±0.05% residual gain error** and **±0.05° alignment** after calibration. Check off-axis sensitivity, stiffness, overload survival and mounting. Reserve multi-axis sensing for the drag problem."}]}], "queryIds": ["fixed_mechanics_contract", "force_position_parts", "joint_budget_plan", "single_axis_prototype_scope", "loadcell_scope_evidence"], "fragments": [{"kind": "prose", "id": "report:nested:results:force-and-position-measurement:part-0", "value": "### Force and position measurement"}]}, {"id": "report:nested:results:acceleration-measurement", "title": "Acceleration measurement", "depth": 3, "path": ["Results", "Acceleration measurement"], "children": [{"id": "report:nested:results:acceleration-measurement:intro", "title": "Intro", "depth": 4, "path": ["Results", "Acceleration measurement", "Intro"], "children": [], "queryIds": ["rl_budget_parts", "rl_budget_sensing_contract", "fixed_mechanics_contract", "budget_accelerometer_stress", "single_axis_prototype_scope", "adc_parts_reviewed"], "fragments": [{"kind": "prose", "id": "report:nested:results:acceleration-measurement:intro:part-0", "value": "#### Intro"}, {"kind": "prose", "id": "report:nested:results:acceleration-measurement:intro:part-1", "value": "An accelerometer on S measures the tool motion needed to remove its inertial contribution from the force reading."}]}, {"id": "report:nested:results:acceleration-measurement:question", "title": "Question", "depth": 4, "path": ["Results", "Acceleration measurement", "Question"], "children": [], "queryIds": ["rl_budget_parts", "rl_budget_sensing_contract", "fixed_mechanics_contract", "budget_accelerometer_stress", "single_axis_prototype_scope", "adc_parts_reviewed"], "fragments": [{"kind": "prose", "id": "report:nested:results:acceleration-measurement:question:part-0", "value": "#### Question"}, {"kind": "prose", "id": "report:nested:results:acceleration-measurement:question:part-1", "value": "How accurate must it be, and does it also need an ADC?"}]}, {"id": "report:nested:results:acceleration-measurement:results", "title": "Results", "depth": 4, "path": ["Results", "Acceleration measurement", "Results"], "children": [], "queryIds": ["rl_budget_parts", "rl_budget_sensing_contract", "fixed_mechanics_contract", "budget_accelerometer_stress", "single_axis_prototype_scope", "adc_parts_reviewed"], "fragments": [{"kind": "prose", "id": "report:nested:results:acceleration-measurement:results:part-0", "value": "#### Results"}, {"kind": "prose", "id": "report:nested:results:acceleration-measurement:results:part-1", "value": "An acceleration error of **0.01 m/s² becomes 0.02 N force error at S = 2 kg**. Averaging can reduce random noise; it cannot remove fixed bias, scale error or a timing mismatch with the load-cell signal.\n\nThe reference is an **ADXL354C**, an analogue accelerometer whose outputs need conversion. The recorded planar model acquires two axes; the first-prototype four-channel ADC can accommodate one load-cell output and all three acceleration outputs. A digital accelerometer has an internal converter but still needs response-delay and noise checks. The model's reference-conditioned acceleration noise is **0.0187 m/s² RMS**, before ADC noise; this is not guaranteed installed output noise."}]}, {"id": "report:nested:results:acceleration-measurement:recommendation", "title": "Recommendation", "depth": 4, "path": ["Results", "Acceleration measurement", "Recommendation"], "children": [], "queryIds": ["rl_budget_parts", "rl_budget_sensing_contract", "fixed_mechanics_contract", "budget_accelerometer_stress", "single_axis_prototype_scope", "adc_parts_reviewed"], "fragments": [{"kind": "prose", "id": "report:nested:results:acceleration-measurement:recommendation:part-0", "value": "#### Recommendation"}, {"kind": "prose", "id": "report:nested:results:acceleration-measurement:recommendation:part-1", "value": "Use the ADXL354C as the development reference, rigidly mounted on S. Target **±0.005 m/s² residual bias**, **±0.25% scale residual** and synchronized force/acceleration acquisition. Use three acceleration axes for spatial motion. Test vibration from the running spindle: resolution alone does not establish useful acceleration accuracy."}]}], "queryIds": ["rl_budget_parts", "rl_budget_sensing_contract", "fixed_mechanics_contract", "budget_accelerometer_stress", "single_axis_prototype_scope", "adc_parts_reviewed"], "fragments": [{"kind": "prose", "id": "report:nested:results:acceleration-measurement:part-0", "value": "### Acceleration measurement"}]}, {"id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing", "title": "Acquisition electronics: amplifier, ADC and timing", "depth": 3, "path": ["Results", "Acquisition electronics: amplifier, ADC and timing"], "children": [{"id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:intro", "title": "Intro", "depth": 4, "path": ["Results", "Acquisition electronics: amplifier, ADC and timing", "Intro"], "children": [], "queryIds": ["fixed_acquisition_reference", "rl_budget_parts", "rl_budget_sensing_contract", "budget_adc_screen", "adc_native_diagnostics", "adc_parts_reviewed", "single_axis_prototype_scope"], "fragments": [{"kind": "prose", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:intro:part-0", "value": "#### Intro"}, {"kind": "prose", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:intro:part-1", "value": "An **ADC** turns analogue voltages into numbers. The controller needs those numbers to estimate contact force and decide coil current. The instrumentation amplifier first strengthens the small bridge signal and limits unwanted high-frequency content."}]}, {"id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:question", "title": "Question", "depth": 4, "path": ["Results", "Acquisition electronics: amplifier, ADC and timing", "Question"], "children": [], "queryIds": ["fixed_acquisition_reference", "rl_budget_parts", "rl_budget_sensing_contract", "budget_adc_screen", "adc_native_diagnostics", "adc_parts_reviewed", "single_axis_prototype_scope"], "fragments": [{"kind": "prose", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:question:part-0", "value": "#### Question"}, {"kind": "prose", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:question:part-1", "value": "Is a separate ADC necessary? How good must it be, and what is the cheapest option for an acceptable force error?"}]}, {"id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:results", "title": "Results", "depth": 4, "path": ["Results", "Acquisition electronics: amplifier, ADC and timing", "Results"], "children": [], "queryIds": ["fixed_acquisition_reference", "rl_budget_parts", "rl_budget_sensing_contract", "budget_adc_screen", "adc_native_diagnostics", "adc_parts_reviewed", "single_axis_prototype_scope"], "fragments": [{"kind": "prose", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:results:part-0", "value": "#### Results"}, {"kind": "prose", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:results:part-1", "value": "**Conversion is necessary for analogue sensors; a separate converter chip is not inherently necessary.** A microcontroller may already contain ADCs, or a digital load cell may contain one. What matters is the complete acquisition path, including noise, analogue filtering, conversion, communication and timestamps.\n\n**Resolution** sets one digital step; advertised bits do not guarantee accuracy. **Sampling rate** counts fresh readings per channel. **Bandwidth** describes changes the sensor/filter can follow; rapid sampling cannot restore changes a slow filter removed. Delay and channel mismatch affect inertia correction and vibration feedback.\n\nThe reference **ADS131M08** supplies eight simultaneous channels at **30,000 fresh samples/s per channel**, followed by **10,000 controller updates/s**. Its modeled path includes matched two-pole **1.9 kHz responses**, about **49.6 µs converter group delay**, a **50 µs smoothing filter running at the ADC output rate**, and **20 µs pipeline including SPI**. “Matched” means force and acceleration see comparable timing and filtering, rather than merely sharing an advertised cutoff. [TI datasheet](https://www.ti.com/lit/ds/symlink/ads131m08.pdf).\n\nThe fixed-controller diagnostics compare seven known development cases, changing either code spacing or actual converter rate/noise/delay. All startup samples count; the controller was not retuned."}, {"kind": "table", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:results:table-1", "title": "Results · Acquisition electronics: amplifier, ADC and timing", "queryIds": ["fixed_acquisition_reference", "rl_budget_parts", "rl_budget_sensing_contract", "budget_adc_screen", "adc_native_diagnostics", "adc_parts_reviewed", "single_axis_prototype_scope"], "headers": ["Converter setting", "Cases passing ±0.5 N", "Largest recorded error"], "rows": [{"column0": "30 ksample/s, 24-bit codes", "column1": "7/7", "column2": "0.495 N"}, {"column0": "30 ksample/s, 16-bit codes", "column1": "7/7", "column2": "0.492 N"}, {"column0": "30 ksample/s, 14-bit codes", "column1": "6/7", "column2": "0.502 N"}, {"column0": "30 ksample/s, 12-bit codes", "column1": "4/7", "column2": "0.553 N"}, {"column0": "15 ksample/s, 24-bit codes", "column1": "6/7", "column2": "0.539 N"}, {"column0": "7.5 ksample/s, 24-bit codes", "column1": "0/7", "column2": "52.218 N; all stopped during startup"}], "rightAligned": [false, true, true]}, {"kind": "figure", "id": "inertial:adc-fixed-diagnostics-20261006", "title": "ADC resolution and sampling-rate comparisons on fixed mechanics", "caption": "42 completed diagnostic recordings, not a fresh qualification grid. Bit tests retain M08 noise and timing; rate tests change converter delay too. The stopped 7.5 ksample/s recordings are shown separately because they never reach the bump.", "queryId": "adc_native_diagnostics", "asset": "figure4"}, {"kind": "prose", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:results:part-2", "value": "At the modeled scaling, **16 bits gives 0.00488 N per force step and 0.00359 m/s² per acceleration step**. This looks usable, but does not qualify a real 16-bit chip's noise or accuracy. Lower sample rates reduce converter noise while increasing delay from **49.6 to 99.6 or 199.6 µs**. Here that timing change makes control worse. The experiments support keeping 30 ksample/s with this controller; they do not establish a universal minimum or an optimal analogue cutoff."}, {"kind": "table", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:results:table-2", "title": "Results · Acquisition electronics: amplifier, ADC and timing", "queryIds": ["fixed_acquisition_reference", "rl_budget_parts", "rl_budget_sensing_contract", "budget_adc_screen", "adc_native_diagnostics", "adc_parts_reviewed", "single_axis_prototype_scope"], "headers": ["ADC option", "Recorded chip cost, VAT included", "Decision"], "rows": [{"column0": "ADS131M04, four simultaneous channels", "column1": "€7.15", "column2": "Fits one force plus three acceleration outputs"}, {"column0": "ADS131M08, eight simultaneous channels", "column1": "€11.43", "column2": "Keep for the recorded eight-channel arrangement or later expansion"}, {"column0": "MCP3208, multiplexed 12-bit", "column1": "€2.95", "column2": "Code spacing, channel skew and rate need a different qualified design"}, {"column0": "Existing microcontroller ADC", "column1": "€0 additional chip cost", "column2": "Potential saving; measured noise, filtering and timing still unproven"}], "rightAligned": [false, true, false]}, {"kind": "prose", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:results:part-3", "value": "*Quantity-one prices observed 6 October 2026; other electronics and shipping excluded. [Parts, sources and experiment details](/home/tommie/Projects/actuator-model/acf_simulink/experiments/report_readability_20261006/adc/README.md).*\n\nMCP3208's **100 ksample/s is aggregate**, giving at most 25 ksample/s each for four sequential channels at 5 V. Neither it nor a built-in microcontroller ADC inherits the simultaneous-converter results. M04's reviewed OSR128 noise and filter topology match M08's corresponding setting. [M04 datasheet](https://www.ti.com/lit/ds/symlink/ads131m04.pdf)."}]}, {"id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:recommendation", "title": "Recommendation", "depth": 4, "path": ["Results", "Acquisition electronics: amplifier, ADC and timing", "Recommendation"], "children": [], "queryIds": ["fixed_acquisition_reference", "rl_budget_parts", "rl_budget_sensing_contract", "budget_adc_screen", "adc_native_diagnostics", "adc_parts_reviewed", "single_axis_prototype_scope"], "fragments": [{"kind": "prose", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:recommendation:part-0", "value": "#### Recommendation"}, {"kind": "prose", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:recommendation:part-1", "value": "Choose **ADS131M04** for the first prototype. It is the cheapest reviewed option that plausibly retains the reference timing/noise envelope, and keeps the ADXL354C-plus-ADC chips below €100 at the recorded prices. Keep **30 ksample/s per channel** and the modeled matched **1.9 kHz response** initially. Validate the assembled chain and one-axis controller before claiming performance; cheaper acquisition remains a separate development option."}]}], "queryIds": ["fixed_acquisition_reference", "rl_budget_parts", "rl_budget_sensing_contract", "budget_adc_screen", "adc_native_diagnostics", "adc_parts_reviewed", "single_axis_prototype_scope"], "fragments": [{"kind": "prose", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:part-0", "value": "### Acquisition electronics: amplifier, ADC and timing"}]}, {"id": "report:nested:results:fast-force-controller", "title": "Fast force controller", "depth": 3, "path": ["Results", "Fast force controller"], "children": [{"id": "report:nested:results:fast-force-controller:intro", "title": "Intro", "depth": 4, "path": ["Results", "Fast force controller", "Intro"], "children": [], "queryIds": ["fixed_mechanics_contract", "fixed_development_results", "fixed_qualification_results", "fixed_control_waveform", "fixed_controller_contract", "explained_cell_mode"], "fragments": [{"kind": "prose", "id": "report:nested:results:fast-force-controller:intro:part-0", "value": "#### Intro"}, {"kind": "prose", "id": "report:nested:results:fast-force-controller:intro:part-1", "value": "The coil handles rapid force changes. The robot has a slower role: keeping the actuator away from its travel limits."}]}, {"id": "report:nested:results:fast-force-controller:question", "title": "Question", "depth": 4, "path": ["Results", "Fast force controller", "Question"], "children": [], "queryIds": ["fixed_mechanics_contract", "fixed_development_results", "fixed_qualification_results", "fixed_control_waveform", "fixed_controller_contract", "explained_cell_mode"], "fragments": [{"kind": "prose", "id": "report:nested:results:fast-force-controller:question:part-0", "value": "#### Question"}, {"kind": "prose", "id": "report:nested:results:fast-force-controller:question:part-1", "value": "What does “cell-mode feedback” actually do, and why does it improve the bump response?"}]}, {"id": "report:nested:results:fast-force-controller:results", "title": "Results", "depth": 4, "path": ["Results", "Fast force controller", "Results"], "children": [], "queryIds": ["fixed_mechanics_contract", "fixed_development_results", "fixed_qualification_results", "fixed_control_waveform", "fixed_controller_contract", "explained_cell_mode"], "fragments": [{"kind": "prose", "id": "report:nested:results:fast-force-controller:results:part-0", "value": "#### Results"}, {"kind": "prose", "id": "report:nested:results:fast-force-controller:results:part-1", "value": "The main **PI controller** changes current in proportion to force error and accumulated error. Its gains are **0.0246 A/N and 16.4 A/(N·s)**, with a 1 kHz force-feedback filter. Measured-inertia feedforward adds effort for tool motion before a large force error develops. A body-motion observer estimates A's unmeasured movement from force, acceleration, relative position and issued robot commands.\n\n**Cell-mode feedback is a separate vibration correction.** It selects the load-cell ringing band and times a small extra coil force to oppose the oscillating motion. Its combined frequency/phase filter has no steady-state contribution; the ordinary force loop still sets the average pressing force. Correction is bounded to **±0.05 A**, or approximately **±1.22 N coil force**.\n\nTiming is essential. Sensors, ADC filters and the current driver delay the correction. If we simply push against an old measurement, the holder may already be moving the other way and the push can feed the vibration. The selected filter compensates the identified response near 1.64 kHz. It is a targeted correction, not a general guarantee of damping at every frequency."}, {"kind": "figure", "id": "inertial:fixed-mechanics-force-limit-20261005", "title": "Measured improvement from cell-mode feedback in a development case", "caption": "Same 2 kg tool, 50 N target, 90° orientation and noise seed. Complete-recording error falls from 1.074 to 0.459 N, and post-bump cell-band power falls by 14.6 dB. This is a matched development example, not the worst fresh test.", "queryId": "fixed_control_waveform", "asset": "figure5"}]}, {"id": "report:nested:results:fast-force-controller:recommendation", "title": "Recommendation", "depth": 4, "path": ["Results", "Fast force controller", "Recommendation"], "children": [], "queryIds": ["fixed_mechanics_contract", "fixed_development_results", "fixed_qualification_results", "fixed_control_waveform", "fixed_controller_contract", "explained_cell_mode"], "fragments": [{"kind": "prose", "id": "report:nested:results:fast-force-controller:recommendation:part-0", "value": "#### Recommendation"}, {"kind": "prose", "id": "report:nested:results:fast-force-controller:recommendation:part-1", "value": "Use this inspectable deterministic architecture as the starting point. Identify real cell and driver phase before retuning. The selected family passed its eleven development points, but the fresh results show that more robust sensing and vibration control are still needed."}]}], "queryIds": ["fixed_mechanics_contract", "fixed_development_results", "fixed_qualification_results", "fixed_control_waveform", "fixed_controller_contract", "explained_cell_mode"], "fragments": [{"kind": "prose", "id": "report:nested:results:fast-force-controller:part-0", "value": "### Fast force controller"}]}, {"id": "report:nested:results:robot-commands-and-recentering", "title": "Robot commands and recentering", "depth": 3, "path": ["Results", "Robot commands and recentering"], "children": [{"id": "report:nested:results:robot-commands-and-recentering:intro", "title": "Intro", "depth": 4, "path": ["Results", "Robot commands and recentering", "Intro"], "children": [], "queryIds": ["fixed_mechanics_contract", "fixed_development_results", "fixed_qualification_results", "rl_method_contract", "final_robot_OAT"], "fragments": [{"kind": "prose", "id": "report:nested:results:robot-commands-and-recentering:intro:part-0", "value": "#### Intro"}, {"kind": "prose", "id": "report:nested:results:robot-commands-and-recentering:intro:part-1", "value": "A robot correction can arrive after the force condition that triggered it has disappeared."}]}, {"id": "report:nested:results:robot-commands-and-recentering:question", "title": "Question", "depth": 4, "path": ["Results", "Robot commands and recentering", "Question"], "children": [], "queryIds": ["fixed_mechanics_contract", "fixed_development_results", "fixed_qualification_results", "rl_method_contract", "final_robot_OAT"], "fragments": [{"kind": "prose", "id": "report:nested:results:robot-commands-and-recentering:question:part-0", "value": "#### Question"}, {"kind": "prose", "id": "report:nested:results:robot-commands-and-recentering:question:part-1", "value": "How do we avoid turning recentering into delayed positive feedback?"}]}, {"id": "report:nested:results:robot-commands-and-recentering:results", "title": "Results", "depth": 4, "path": ["Results", "Robot commands and recentering", "Results"], "children": [], "queryIds": ["fixed_mechanics_contract", "fixed_development_results", "fixed_qualification_results", "rl_method_contract", "final_robot_OAT"], "fragments": [{"kind": "prose", "id": "report:nested:results:robot-commands-and-recentering:results:part-0", "value": "#### Results"}, {"kind": "prose", "id": "report:nested:results:robot-commands-and-recentering:results:part-1", "value": "New **100 Hz commands** require stable force: a **0.08 N RMS variation gate** resets a **100 ms dwell**, alongside a slower stability condition. The predictor retains issued commands, approximately 80 ms delay and 60 ms robot response. Closing the gate does not cancel commands already queued. Travel within **±7.5 mm** about the midpoint incurs no centering cost."}]}, {"id": "report:nested:results:robot-commands-and-recentering:recommendation", "title": "Recommendation", "depth": 4, "path": ["Results", "Robot commands and recentering", "Recommendation"], "children": [], "queryIds": ["fixed_mechanics_contract", "fixed_development_results", "fixed_qualification_results", "rl_method_contract", "final_robot_OAT"], "fragments": [{"kind": "prose", "id": "report:nested:results:robot-commands-and-recentering:recommendation:part-0", "value": "#### Recommendation"}, {"kind": "prose", "id": "report:nested:results:robot-commands-and-recentering:recommendation:part-1", "value": "Keep conservative, delay-aware recentering and the stability gate. Identify the robot's actual timing and test repeated bumps plus sustained drift. The long-test travel stop shows why a good short bump response is insufficient."}]}], "queryIds": ["fixed_mechanics_contract", "fixed_development_results", "fixed_qualification_results", "rl_method_contract", "final_robot_OAT"], "fragments": [{"kind": "prose", "id": "report:nested:results:robot-commands-and-recentering:part-0", "value": "### Robot commands and recentering"}]}, {"id": "report:nested:results:learned-control-policy", "title": "Learned control policy", "depth": 3, "path": ["Results", "Learned control policy"], "children": [{"id": "report:nested:results:learned-control-policy:intro", "title": "Intro", "depth": 4, "path": ["Results", "Learned control policy", "Intro"], "children": [], "queryIds": ["rl_selected_candidate", "rl_nominal_grid", "rl_fresh_tests", "rl_long_tests"], "fragments": [{"kind": "prose", "id": "report:nested:results:learned-control-policy:intro:part-0", "value": "#### Intro"}, {"kind": "prose", "id": "report:nested:results:learned-control-policy:intro:part-1", "value": "We also trained one recurrent policy to request coil current and robot correction from measurement history."}]}, {"id": "report:nested:results:learned-control-policy:question", "title": "Question", "depth": 4, "path": ["Results", "Learned control policy", "Question"], "children": [], "queryIds": ["rl_selected_candidate", "rl_nominal_grid", "rl_fresh_tests", "rl_long_tests"], "fragments": [{"kind": "prose", "id": "report:nested:results:learned-control-policy:question:part-0", "value": "#### Question"}, {"kind": "prose", "id": "report:nested:results:learned-control-policy:question:part-1", "value": "Should learning replace the deterministic controller?"}]}, {"id": "report:nested:results:learned-control-policy:results", "title": "Results", "depth": 4, "path": ["Results", "Learned control policy", "Results"], "children": [], "queryIds": ["rl_selected_candidate", "rl_nominal_grid", "rl_fresh_tests", "rl_long_tests"], "fragments": [{"kind": "prose", "id": "report:nested:results:learned-control-policy:results:part-0", "value": "#### Results"}, {"kind": "prose", "id": "report:nested:results:learned-control-policy:results:part-1", "value": "On the earlier mechanics, the retained policy passed 700 nominal tests but only 30/32 fresh and 3/4 long tests; one long case reached a travel stop. Those results do not transfer to the newly prescribed mechanics."}]}, {"id": "report:nested:results:learned-control-policy:recommendation", "title": "Recommendation", "depth": 4, "path": ["Results", "Learned control policy", "Recommendation"], "children": [], "queryIds": ["rl_selected_candidate", "rl_nominal_grid", "rl_fresh_tests", "rl_long_tests"], "fragments": [{"kind": "prose", "id": "report:nested:results:learned-control-policy:recommendation:part-0", "value": "#### Recommendation"}, {"kind": "prose", "id": "report:nested:results:learned-control-policy:recommendation:part-1", "value": "Keep it as research evidence. Retrain and independently test any learned candidate on the current plant before considering it for the prototype."}]}], "queryIds": ["rl_selected_candidate", "rl_nominal_grid", "rl_fresh_tests", "rl_long_tests"], "fragments": [{"kind": "prose", "id": "report:nested:results:learned-control-policy:part-0", "value": "### Learned control policy"}]}, {"id": "report:nested:results:calibration-model-qualification-and-prototype-validation", "title": "Calibration, model qualification and prototype validation", "depth": 3, "path": ["Results", "Calibration, model qualification and prototype validation"], "children": [{"id": "report:nested:results:calibration-model-qualification-and-prototype-validation:intro", "title": "Intro", "depth": 4, "path": ["Results", "Calibration, model qualification and prototype validation", "Intro"], "children": [], "queryIds": ["fixed_mechanics_contract", "fixed_development_results", "fixed_qualification_results", "fixed_voltage_diagnostics", "fixed_controller_contract", "fixed_native_verification", "rl_budget_sensing_contract", "joint_budget_plan", "single_axis_prototype_scope"], "fragments": [{"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:intro:part-0", "value": "#### Intro"}, {"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:intro:part-1", "value": "The simulation tests a stated physical and sensing model, not every disturbance from a real sanding machine."}]}, {"id": "report:nested:results:calibration-model-qualification-and-prototype-validation:question", "title": "Question", "depth": 4, "path": ["Results", "Calibration, model qualification and prototype validation", "Question"], "children": [], "queryIds": ["fixed_mechanics_contract", "fixed_development_results", "fixed_qualification_results", "fixed_voltage_diagnostics", "fixed_controller_contract", "fixed_native_verification", "rl_budget_sensing_contract", "joint_budget_plan", "single_axis_prototype_scope"], "fragments": [{"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:question:part-0", "value": "#### Question"}, {"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:question:part-1", "value": "Which checks turn this development recommendation into an accepted system?"}]}, {"id": "report:nested:results:calibration-model-qualification-and-prototype-validation:results", "title": "Results", "depth": 4, "path": ["Results", "Calibration, model qualification and prototype validation", "Results"], "children": [], "queryIds": ["fixed_mechanics_contract", "fixed_development_results", "fixed_qualification_results", "fixed_voltage_diagnostics", "fixed_controller_contract", "fixed_native_verification", "rl_budget_sensing_contract", "joint_budget_plan", "single_axis_prototype_scope"], "fragments": [{"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:results:part-0", "value": "#### Results"}, {"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:results:part-1", "value": "The model assumes fixed orientation, planar translation, known tool mass and preloaded smooth contact. Pad compliance, spindle rotation, angular inertia, frame flexibility, temperature drift and sanding vibration need assembled tests. Force noise is bounded uniform; acceleration noise is Gaussian. Offsets, scale errors, timing and ADC effects are separately represented. Noise fields are normalized to a fixed **3,177 Hz reference bandwidth**, not guaranteed installed RMS.\n\nMATLAB reproduces the reference nominal/stress failures within **31 µN waveform difference**, although stricter parity checks remain failed. Locked inputs, compact results and selected histories are retained; bulk histories were removed in the [storage audit](/home/tommie/Projects/actuator-model/acf_simulink/validation/storage_cleanup_20261006/README.md)."}]}, {"id": "report:nested:results:calibration-model-qualification-and-prototype-validation:recommendation", "title": "Recommendation", "depth": 4, "path": ["Results", "Calibration, model qualification and prototype validation", "Recommendation"], "children": [], "queryIds": ["fixed_mechanics_contract", "fixed_development_results", "fixed_qualification_results", "fixed_voltage_diagnostics", "fixed_controller_contract", "fixed_native_verification", "rl_budget_sensing_contract", "joint_budget_plan", "single_axis_prototype_scope"], "fragments": [{"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:recommendation:part-0", "value": "#### Recommendation"}, {"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:recommendation:part-1", "value": "Measure assembled masses, modes, friction, current response and sensor timing; calibrate axial load response, off-axis sensitivity and acceleration alignment. Target **≤2 µs relative timing residual**. Compare reconstructed force with an independent reference on the scoped bench setup through repeated bumps and long drift. Then test powered sanding and the deferred drag extension. Aim for **≤0.45 N peak error**, leaving 0.05 N reserve.\n\nThe [fixed-model guide](/home/tommie/Projects/actuator-model/acf_simulink/generated/fixed_upper_20261005/GETTING_STARTED_FIXED.md), [ADC details](/home/tommie/Projects/actuator-model/acf_simulink/experiments/report_readability_20261006/adc/README.md) and [earlier report](/home/tommie/Projects/actuator-model/reports/active-contact-flange-report-rl-3h-20261005.md) provide the instructions and detailed evidence."}]}], "queryIds": ["fixed_mechanics_contract", "fixed_development_results", "fixed_qualification_results", "fixed_voltage_diagnostics", "fixed_controller_contract", "fixed_native_verification", "rl_budget_sensing_contract", "joint_budget_plan", "single_axis_prototype_scope"], "fragments": [{"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:part-0", "value": "### Calibration, model qualification and prototype validation"}]}], "queryIds": ["fixed_mechanics_contract", "fixed_development_results", "fixed_qualification_results", "single_axis_prototype_scope", "explained_nominal_grid"], "fragments": [{"kind": "prose", "id": "report:nested:results:part-0", "value": "## Results"}, {"kind": "prose", "id": "report:nested:results:part-1", "value": "**The current controller is a useful development baseline, but the prescribed arrangement does not yet meet the complete requirement.** The following recorded tests used multi-axis reconstruction. They inform the design; they do not qualify the new one-axis prototype. The controller was locked before these fresh tests:"}, {"kind": "table", "id": "report:nested:results:table-1", "title": "Results", "queryIds": ["fixed_mechanics_contract", "fixed_development_results", "fixed_qualification_results", "single_axis_prototype_scope", "explained_nominal_grid"], "headers": ["Test group", "Passed", "Largest force error", "Hard stops"], "rows": [{"column0": "700 nominal combinations of mass, force and orientation", "column1": "683/700", "column2": "0.580 N", "column3": "0"}, {"column0": "32 sensing/calibration and motion stresses", "column1": "21/32", "column2": "3.948 N", "column3": "0"}, {"column0": "Four repeated-bump/drift recordings, up to 30 s", "column1": "1/4", "column2": "0.691 N", "column3": "1"}], "rightAligned": [false, true, true, true]}, {"kind": "prose", "id": "report:nested:results:part-2", "value": "Every simulation sample counts, including startup. Contact loss or a travel stop fails the recording. Two long tests leave the accepted ±7.5 mm band; one reaches a hard stop after 4.19 s. These recommendations support an **instrumented development prototype**."}, {"kind": "figure", "id": "inertial:fixed-force-operating-grid-20261006", "title": "Where the nominal fixed design meets the force requirement", "caption": "Each square contains the largest recorded error across seven orientations. Outlines use the unrounded 0.5 N threshold. This finite grid does not include the separate calibration/motion stresses or long tests.", "queryId": "explained_nominal_grid", "asset": "figure0"}]}, {"id": "report:nested:recommendation", "title": "Recommendation", "depth": 2, "path": ["Recommendation"], "children": [], "queryIds": ["fixed_mechanics_contract", "fixed_development_results", "fixed_qualification_results", "fixed_voltage_diagnostics", "fixed_controller_contract", "fixed_native_verification", "rl_budget_parts", "rl_budget_sensing_contract", "single_axis_prototype_scope", "adc_native_diagnostics", "adc_parts_reviewed", "actuator_sizing_reviewed"], "fragments": [{"kind": "prose", "id": "report:nested:recommendation:part-0", "value": "## Recommendation"}, {"kind": "prose", "id": "report:nested:recommendation:part-1", "value": "The present controller remains **unqualified across the complete ±0.5 N range**. Prototype measurements and a new independently tested candidate must address the exposed sensing, ringing and long-travel failures before claiming success.\n\n**Build an instrumented voice-coil prototype with the prescribed 20 N/mm undamped upper spring and rigid lower attachment.** Use a 25 mm coil sized for hot continuous force, an adjustable 48 V-rated bipolar driver, **one-axis B–S load sensing**, an S–A encoder and an ADXL354C on S. Acquire the force output and three acceleration outputs with **ADS131M04**. Defer multi-axis drag separation.\n\nStart with the deterministic PI/inertia/observer/cell-mode controller, 30 ksample/s acquisition, 10 kHz force control and stability-gated 100 Hz robot recentering."}]}];
const figureAssets={figure0:figure0,figure1:figure1,figure2:figure2,figure3:figure3,figure4:figure4,figure5:figure5};

function Figure({fragment,queries}){const rows=queries[fragment.queryId]?.rows||[];return <DataComponent id={fragment.id} queryId={fragment.queryId} kind="custom" title={fragment.title} sourceRows={rows} displayRows={rows}><figure className="study-figure"><img src={figureAssets[fragment.asset]} alt={fragment.title} loading="eager"/><RichNarrative id={fragment.id+':caption'} value={fragment.caption}/></figure></DataComponent>}
function InlineCell({value}){return String(value).split(/(\*\*[^*]+\*\*|`[^`]+`)/g).map((part,i)=>part.startsWith('**')?<strong key={i}>{part.slice(2,-2)}</strong>:part.startsWith('`')?<code key={i}>{part.slice(1,-1)}</code>:<React.Fragment key={i}>{part}</React.Fragment>)}
function ReportTable({fragment,queries}){const rows=Object.fromEntries(fragment.queryIds.map(id=>[id,queries[id]?.rows||[]]));return <DataComponent id={fragment.id} queryId={fragment.queryIds[0]} queryIds={fragment.queryIds} kind="table" title={fragment.title} sourceRows={rows[fragment.queryIds[0]]} sourceRowsByQuery={rows} displayRows={fragment.rows}><div className="study-table-wrap" data-reviewed-rows><table className="study-table" aria-label={fragment.title}><thead><tr>{fragment.headers.map((h,i)=><th scope="col" key={i} className={fragment.rightAligned[i]?'numeric':''}>{h}</th>)}</tr></thead><tbody>{fragment.rows.map((row,k)=><tr key={k}>{fragment.headers.map((_,i)=><td key={i} className={fragment.rightAligned[i]?'numeric':''}><InlineCell value={row['column'+i]}/></td>)}</tr>)}</tbody></table></div></DataComponent>}
function StudyNode({node,queries,qualificationTable}){const rows=Object.fromEntries(node.queryIds.map(id=>[id,queries[id]?.rows||[]]));const body=<>{node.fragments.map(f=>f.kind==='figure'?<Figure key={f.id} fragment={f} queries={queries}/>:f.kind==='table'?<ReportTable key={f.id} fragment={f} queries={queries}/>:<RichNarrative key={f.id} id={f.id} value={f.value}/>)}{node.title==='Full scientific-reference grid and numerical qualification'?qualificationTable:null}</>;return <section className="study-node" data-depth={node.depth} data-phase={node.title} id={node.id}><div className="study-node-body">{node.queryIds.length?<ReportSection id={node.id+':evidence'} title={node.title} showHeading={false} queryId={node.queryIds[0]} queryIds={node.queryIds} sourceRows={rows[node.queryIds[0]]} sourceRowsByQuery={rows}>{body}</ReportSection>:body}</div>{node.children.map(child=><StudyNode key={child.id} node={child} queries={queries} qualificationTable={qualificationTable}/>)}</section>}
export function ReportContent(){const {snapshot,appTitle}=useDataApp();const [mass,setMass]=useState('all'),[force,setForce]=useState('all');const range=snapshot.queries.qualified_range?.rows||[];const shown=range.filter(r=>(mass==='all'||r.massS_kg===Number(mass))&&(force==='all'||r.reference_N===Number(force)));const c=(field,label)=>({field,label});const n=(field,label)=>({field,label,renderCell:v=>typeof v==='number'?v.toFixed(3):'—'});const table=<DataComponent id="inertial:qualified-case-table" queryId="qualified_range" kind="table" title="Inspect the qualification recordings" sourceRows={range} displayRows={shown}><DataTable rows={shown} caption="Native full-history qualification" toolbarControls={<><label>Tool S <select aria-label="Tool S" value={mass} onChange={e=>setMass(e.target.value)}><option value="all">All masses</option>{[...new Set(range.map(r=>r.massS_kg))].sort((a,b)=>a-b).map(v=><option key={v} value={v}>{v} kg</option>)}</select></label><label>Target <select aria-label="Target force" value={force} onChange={e=>setForce(e.target.value)}><option value="all">All forces</option>{[...new Set(range.map(r=>r.reference_N))].sort((a,b)=>a-b).map(v=><option key={v} value={v}>{v} N</option>)}</select></label></>} columns={[c('massS_kg','S (kg)'),c('reference_N','Target (N)'),c('angle_deg','Angle (°)'),c('mu','Friction'),c('seedRequested','Noise seed'),n('peakNormalForceError_N','Peak error (N)'),n('peakCurrent_A','Current (A)'),n('peakVoltage_V','Voltage (V)'),c('passed','Pass')]}/></DataComponent>;return <article className="report-content" aria-label="Active contact flange nested design study"><header className="report-hero"><h1>{appTitle}</h1></header>{sections.map(node=><StudyNode key={node.id} node={node} queries={snapshot.queries} qualificationTable={table}/>)}</article>}
